mapper.select:
WITH latest_ml AS ( SELECT DISTINCT ON (user_id) churn_score_id, user_id, score, risk_level, scored_at FROM churn_score WHERE source = 'ML'
AND scored_at > NOW() - INTERVAL '7 days' AND scored_at <= NOW() ORDER BY user_id, scored_at DESC, churn_score_id DESC ) SELECT ml.user_id AS userId, ml.churn_score_id AS churnScoreId, ml.score FROM latest_ml ml JOIN users u ON u.user_id = ml.user_id WHERE ml.risk_level = 'HIGH' AND u.status = 'ACTIVE' AND u.role = 'ROLE_USER' AND NOT EXISTS ( SELECT 1 FROM churn_score rule_score WHERE rule_score.user_id = ml.user_id AND rule_score.source = 'RULE'
AND rule_score.scored_at > NOW() - INTERVAL '7 days' AND rule_score.scored_at <= NOW() AND rule_score.risk_type IS NOT NULL ) AND NOT EXISTS ( SELECT 1 FROM retention_intervention intervention WHERE intervention.user_id = ml.user_id AND intervention.created_at > NOW() - INTERVAL '7 days' ) ORDER BY ml.score DESC, ml.user_id LIMIT #{limit}
